253			RepetitionPenalty:  req.RepetitionPenalty,
254			Seed:               seed,
255			SamplingSource:     req.SamplingSource,
256			Reasoning:          req.Reasoning,
257			NoStream:           req.NoStream,
258			MaxTokens:          req.MaxTokens,
259			ReasoningByteLimit: req.ReasoningByteLimit,
260			Compactor:          compactor,
261			CachePolicy:        req.CachePolicy,
262			PlanningMode:       req.PlanningMode || req.ToolPreset == "benchmark",
263		}
264		result, runErr := agentcore.Run(cancelCtx, loopReq)
265		if shouldRetryNativeNoStream(req.NoStream, result, runErr) {
266			loopReq.NoStream = true
267			result, runErr = agentcore.Run(cancelCtx, loopReq)
268		}
269	
270		finalProvider := actualProvider
271		if result.SelectedProvider != "" {
272			finalProvider = result.SelectedProvider
273		}
274		finalModel := actualModel
275		if result.ResolvedModel != "" {
276			finalModel = result.ResolvedModel
277		}
278		final := harnesses.FinalData{
279			DurationMS: time.Since(req.Started).Milliseconds(),
280			FinalText:  result.Output,
281			RoutingActual: &harnesses.RoutingActual{
282				Harness:            actualHarness,
283				Provider:           finalProvider,
284				ServerInstance:     req.Decision.ServerInstance,
285				Model:              finalModel,
286				FallbackChainFired: append([]string(nil), result.AttemptedProviders...),
287			},
288		}
289		final.Usage = &harnesses.FinalUsage{
290			InputTokens:      harnesses.IntPtr(result.Tokens.Input),
291			OutputTokens:     harnesses.IntPtr(result.Tokens.Output),
292			CacheReadTokens:  nil,
293			CacheWriteTokens: nil,
294			TotalTokens:      harnesses.IntPtr(result.Tokens.Total),
295			Source:           harnesses.UsageSourceFallback,
296		}
297		if result.Tokens.CacheRead > 0 {
298			final.Usage.CacheReadTokens = harnesses.IntPtr(result.Tokens.CacheRead)
299		}
300		if result.Tokens.CacheWrite > 0 {
301			final.Usage.CacheWriteTokens = harnesses.IntPtr(result.Tokens.CacheWrite)
302		}
303		if result.Tokens.CacheRead > 0 || result.Tokens.CacheWrite > 0 {
304			final.Usage.CacheTokens = harnesses.IntPtr(result.Tokens.CacheRead + result.Tokens.CacheWrite)
305		}
306		if result.CostUSD > 0 {
307			final.CostUSD = result.CostUSD
308		}
309		if result.Output != "" && cb.EmitEvent != nil {
310			cb.EmitEvent(harnesses.EventTypeTextDelta, harnesses.TextDeltaData{Text: result.Output})
311		}
312		if cb.BeforeFinal != nil {
313			cb.BeforeFinal(final)
314		}
315		switch {
316		case stalled.Load():
317			final.Status = "stalled"
318			reason, _ := stallReason.Load().(string)
319			if cb.EmitEvent != nil {
320				cb.EmitEvent(harnesses.EventTypeStall, map[string]any{
321					"reason": reason,
322					"count":  stallCount.Load(),
323				})
324			}
325			final.Error = reason
326		case ctx.Err() == context.DeadlineExceeded || (req.Timeout > 0 && time.Since(req.Started) >= req.Timeout):
327			final.Status = "timed_out"
328			final.Error = "wall-clock timeout"
329		case ctx.Err() == context.Canceled:
330			final.Status = "cancelled"
331		case runErr != nil:
332			final.Status = "failed"
333			final.Error = runErr.Error()
334		case result.Status == agentcore.StatusError:
335			final.Status = "failed"
336			if result.Error != nil {
337				final.Error = result.Error.Error()
338			}
339		case result.Status == agentcore.StatusIterationLimit:
340			final.Status = string(agentcore.StatusIterationLimit)
341		default:
342			final.Status = "success"
343		}
344		if final.Status == "failed" && final.Error != "" && final.RoutingActual != nil {
345			final.RoutingActual.FailureClass = classifyDispatchFailure(final.Error)
346		}
347		if final.RoutingActual != nil && final.Usage != nil && cb.ObserveTokenUsage != nil {
348			cb.ObserveTokenUsage(final.RoutingActual.Provider, finalUsageTotalTokens(final.Usage), time.Now())
349		}
350		finalize(cb, final)
351	}
