377	func (p *nativeRouteProvider) Chat(ctx context.Context, messages []agentcore.Message, tools []agentcore.ToolDef, opts agentcore.Options) (agentcore.Response, error) {
378		candidate, ok := p.selectedCandidate()
379		if !ok {
380			return agentcore.Response{}, fmt.Errorf("agent: route %q has no selected provider candidate", p.routeKey)
381		}
382		p.attempted = append(p.attempted, candidate.Provider)
383		req := NativeProviderRequest{
384			Provider: candidate.Provider,
385			Model:    candidate.Model,
386			Harness:  p.baseRequest.Harness,
387		}
388		if candidate.Endpoint != "" {
389			req.Provider = endpointProviderRef(candidate.Provider, candidate.Endpoint)
390		}
391		resolved := resolveProvider(p.resolveProvider, req)
392		if resolved.Provider == nil {
393			return agentcore.Response{}, fmt.Errorf("agent: provider error: no provider configured for %q", req.Provider)
394		}
395		opts.Model = candidate.Model
396		resp, err := resolved.Provider.Chat(ctx, messages, tools, opts)
397		if err != nil {
398			return agentcore.Response{}, err
399		}
400		p.selectedProvider = candidate.Provider
401		if resp.Attempt == nil {
402			resp.Attempt = &agentcore.AttemptMetadata{}
403		}
404		resp.Attempt.ProviderName = candidate.Provider
405		resp.Attempt.Route = p.routeKey
406		if resp.Attempt.RequestedModel == "" {
407			resp.Attempt.RequestedModel = p.routeKey
408		}
409		return resp, nil
410	}
