412	func (p *nativeRouteProvider) selectedCandidate() (NativeRouteCandidate, bool) {
413		for _, candidate := range p.candidates {
414			if !candidate.Eligible || candidate.Provider == "" {
415				continue
416			}
417			if p.selectedProvider == "" || candidate.Provider == p.selectedProvider {
418				return candidate, true
419			}
420		}
421		return NativeRouteCandidate{}, false
422	}
