 48			idx    int
 49			models []ModelInfo
 50		}
 51		results := make([]indexedModels, len(names))
 52		var wg sync.WaitGroup
 53	
 54		for i, name := range names {
 55			// Apply provider filter.
 56			if filter.Provider != "" && filter.Provider != name {
 57				results[i] = indexedModels{idx: i, models: nil}
 58				continue
 59			}
 60			// Apply harness filter: providers are served by the "fiz" harness.
