127	func subprocessHarnessModelIDs(name string, cfg harnesses.HarnessConfig) []string {
128		models := append([]string(nil), cfg.Models...)
129		switch name {
130		case "claude":
131			snapshot := claudeharness.DefaultClaudeModelDiscovery()
132			models = appendUniqueModelIDs(models, snapshot.Models...)
133			for _, family := range []string{"sonnet", "opus", "haiku"} {
134				resolved := claudeharness.ResolveClaudeFamilyAlias(family, snapshot)
135				if resolved != family {
136					models = appendUniqueModelIDs(models, resolved)
137				}
138			}
139		case "codex":
140			snapshot := codexharness.DefaultCodexModelDiscovery()
141			models = appendUniqueModelIDs(models, snapshot.Models...)
142			for _, family := range []string{"gpt", "gpt-5"} {
143				resolved := codexharness.ResolveCodexModelAlias(family, snapshot)
144				if resolved != family {
145					models = appendUniqueModelIDs(models, resolved)
146				}
147			}
148		case "gemini":
149			snapshot := geminiharness.DefaultGeminiModelDiscovery()
150			models = appendUniqueModelIDs(models, snapshot.Models...)
151			for _, family := range []string{"gemini", "gemini-2.5"} {
152				resolved := geminiharness.ResolveGeminiModelAlias(family, snapshot)
153				if resolved != family {
154					models = appendUniqueModelIDs(models, resolved)
155				}
156			}
157		}
158		return models
159	}
