161	func resolveSubprocessModelAlias(harness, model string) string {
162		switch harness {
163		case "claude":
164			return claudeCLIExecutableModel(model)
165		case "codex":
166			return codexharness.ResolveCodexModelAlias(model, codexharness.DefaultCodexModelDiscovery())
167		case "gemini":
