174	func claudeCLIExecutableModel(model string) string {
175		normalized := strings.ToLower(strings.TrimSpace(model))
176		switch {
177		case normalized == "sonnet" || strings.HasPrefix(normalized, "sonnet-") || strings.HasPrefix(normalized, "claude-sonnet-"):
178			return "sonnet"
179		case normalized == "opus" || strings.HasPrefix(normalized, "opus-") || strings.HasPrefix(normalized, "claude-opus-"):
180			return "opus"
181		case normalized == "haiku" || strings.HasPrefix(normalized, "haiku-") || strings.HasPrefix(normalized, "claude-haiku-"):
182			return "haiku"
183		default:
184			return model
185		}
186	}
