188	func appendUniqueModelIDs(values []string, additions ...string) []string {
189		for _, value := range additions {
190			value = strings.TrimSpace(value)
191			if value == "" {
192				continue
193			}
194			found := false
195			for _, existing := range values {
196				if existing == value {
197					found = true
198					break
199				}
200			}
201			if !found {
202				values = append(values, value)
203			}
204		}
205		return values
206	}
