 18	// ResolveRoute resolves an under-specified RouteRequest to a concrete
 19	// (Harness, Provider, Model) decision per CONTRACT-003.
 20	//
 21	// The implementation delegates to internal/routing.Resolve — the single
 22	// routing engine that consolidates DDx-side harness-tier ranking and
 23	// fiz-side provider failover ordering.
 24	func (s *service) ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error) {
 25		if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
 26			return nil, err
 27		}
 28		if err := ValidateRole(req.Role); err != nil {
 29			return nil, err
 30		}
 31		if err := ValidateCorrelationID(req.CorrelationID); err != nil {
 32			return nil, err
 33		}
 34		if req.Harness != "" && req.Model != "" {
 35			canonical := harnesses.ResolveHarnessAlias(req.Harness)
 36			if !s.registry.Has(canonical) {
 37				return nil, fmt.Errorf("unknown harness %q", req.Harness)
 38			}
 39			cfg, _ := s.registry.Get(canonical)
 40			if err := validateExplicitHarnessModel(canonical, cfg, req.Model, req.Provider); err != nil {
 41				return nil, err
 42			}
 43		}
 44		s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
 45		cat := serviceRoutingCatalog()
 46		profile := req.Profile
 47		modelRef := req.ModelRef
 48		if modelRef == "" && req.Model == "" && (req.Harness != "" || req.Profile == "smart") {
 49			modelRef = req.Profile
 50		}
 51		providerPreference, err := providerPreferenceForProfile(cat, profile)
 52		if err != nil {
 53			return &RouteDecision{}, err
 54		}
 55		in := s.buildRoutingInputsWithCatalog(ctx, cat)
 56	
 57		resolvedModel, modelCandidates, modelErr := s.resolveModelConstraint(req.Harness, req.Provider, req.Model, in, cat)
 58		if modelErr != nil {
 59			result := &RouteDecision{Candidates: modelCandidates}
 60			s.annotateRouteDecisionEvidence(result)
 61			return result, publicRoutingError(modelErr, result.Candidates)
 62		}
 63	
 64		rReq := routing.Request{
 65			Profile:               profile,
 66			ModelRef:              modelRef,
 67			Model:                 resolvedModel,
 68			Provider:              req.Provider,
 69			Harness:               req.Harness,
 70			Reasoning:             effectiveReasoningString(req.Reasoning),
 71			Permissions:           req.Permissions,
 72			ProviderPreference:    providerPreference,
 73			EstimatedPromptTokens: req.EstimatedPromptTokens,
 74			RequiresTools:         req.RequiresTools,
 75			MinPower:              req.MinPower,
 76			MaxPower:              req.MaxPower,
 77		}
 78		s.applyRouteAttemptCooldowns(&in)
 79		dec, err := routing.Resolve(rReq, in)
 80		if err != nil {
 81			if escalated, edec, eerr := escalateProfileLadder(rReq, in, err); escalated {
 82				dec = edec
 83				err = eerr
 84			}
 85		}
 86		result := routeDecisionFromInternal(dec)
 87		if err != nil {
 88			if result == nil {
 89				result = &RouteDecision{}
 90			}
 91			s.annotateRouteDecisionEvidence(result)
 92			return result, publicRoutingError(err, result.Candidates)
 93		}
 94		s.applyStickyRouteLease(req.CorrelationID, result)
 95		if result != nil && result.Endpoint == "" {
 96			_, endpoint, _ := splitEndpointProviderRef(result.Provider)
 97			result.Endpoint = endpoint
 98		}
 99		s.annotateRouteDecisionEvidence(result)
100		// Cache the decision so RouteStatus can surface LastDecision.
101		if result != nil {
102			result.RequestedProfile = req.Profile
103			result.PowerPolicy = RoutePowerPolicy{
104				Profile:  req.Profile,
105				MinPower: req.MinPower,
106				MaxPower: req.MaxPower,
107			}
108			result.Model = resolveSubprocessModelAlias(result.Harness, result.Model)
109			result.Power = catalogPowerForModel(cat, result.Model)
110		}
111		s.cacheRouteDecision(req.Model, result)
112		return result, nil
113	}
114	
115	func routeDecisionFromInternal(dec *routing.Decision) *RouteDecision {
116		if dec == nil {
117			return nil
118		}
119		return &RouteDecision{
120			Harness:        dec.Harness,
121			Provider:       dec.Provider,
122			Endpoint:       dec.Endpoint,
123			ServerInstance: dec.ServerInstance,
124			Model:          dec.Model,
125			Reason:         dec.Reason,
126			Candidates:     routeCandidatesFromInternal(dec.Candidates),
127		}
128	}
129	
130	func routeCandidatesFromInternal(candidates []routing.Candidate) []RouteCandidate {
131		if len(candidates) == 0 {
132			return nil
133		}
134		out := make([]RouteCandidate, len(candidates))
135		for i, candidate := range candidates {
136			out[i] = routeCandidateFromInternal(candidate)
137		}
138		return out
139	}
