320	// discoverAndRankModels fetches the model list from each provider endpoint and
321	// ranks results against the catalog. IDs preserve discovery order per endpoint.
322	func discoverAndRankModels(ctx context.Context, entry ServiceProviderEntry, cat *modelcatalog.Catalog) []discoveredModelSet {
323		switch normalizeServiceProviderType(entry.Type) {
324		case "openai", "openrouter", "lmstudio", "llama-server", "omlx", "rapid-mlx", "vllm", "ollama", "minimax", "qwen", "zai":
325			endpoints := modelDiscoveryEndpoints(entry)
326			if len(endpoints) == 0 {
327				return nil
328			}
329			out := make([]discoveredModelSet, 0, len(endpoints))
330			for _, endpoint := range endpoints {
331				ids, err := discoverModelsInline(ctx, endpoint.BaseURL, entry.APIKey)
332				if err != nil || len(ids) == 0 {
333					continue
334				}
335				out = append(out, discoveredModelSet{
336					EndpointName:    endpoint.Name,
337					EndpointBaseURL: endpoint.BaseURL,
338					ServerInstance:  endpoint.ServerInstance,
339					IDs:             ids,
340					Ranked:          rankModelsInline(ids, cat),
341				})
342			}
343			return out
344	
345		case "anthropic":
346			// Anthropic does not expose /v1/models for discovery.
347			// If a default model is configured, surface it.
348			if entry.Model != "" {
349				sm := scoredModel{ID: entry.Model, CatalogRef: "", RankPosition: 0}
350				if cat != nil {
351					if ref, ok := catalogRefForModel(cat, entry.Model); ok {
352						sm.CatalogRef = ref
353					}
354				}
355				return []discoveredModelSet{{
356					EndpointName:    "default",
357					EndpointBaseURL: entry.BaseURL,
358					ServerInstance:  serverinstance.Normalize(entry.BaseURL, entry.ServerInstance),
359					IDs:             []string{entry.Model},
360					Ranked:          []scoredModel{sm},
361				}}
362			}
363			return nil
364	
365		default:
366			return nil
367		}
368	}
