412	// discoverModelsInline queries /v1/models and returns model IDs.
413	// Mirrors the inline impl in service_providers.go to avoid import cycle.
414	func discoverModelsInline(ctx context.Context, baseURL, apiKey string) ([]string, error) {
415		base := strings.TrimRight(baseURL, "/")
416		endpoint := base + "/models"
417	
418		req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
419		if err != nil {
420			return nil, fmt.Errorf("discovery: build request: %w", err)
421		}
422		req.Header.Set("Accept", "application/json")
423		if apiKey != "" {
424			req.Header.Set("Authorization", "Bearer "+apiKey)
425		}
426	
427		resp, err := http.DefaultClient.Do(req)
428		if err != nil {
429			return nil, err
430		}
431		defer resp.Body.Close()
432	
433		if resp.StatusCode != http.StatusOK {
434			body, _ := io.ReadAll(io.LimitReader(resp.Body, 512))
435			return nil, fmt.Errorf("discovery: HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
436		}
437	
438		var mr struct {
439			Data []struct {
440				ID string `json:"id"`
441			} `json:"data"`
442		}
443		if err := json.NewDecoder(resp.Body).Decode(&mr); err != nil {
444			return nil, fmt.Errorf("discovery: decode response: %w", err)
445		}
446	
447		ids := make([]string, 0, len(mr.Data))
448		for _, m := range mr.Data {
449			if m.ID != "" {
450				ids = append(ids, m.ID)
451			}
452		}
453		return ids, nil
454	}
