463	// rankModelsInline scores discovered model IDs against the catalog.
464	func rankModelsInline(ids []string, cat *modelcatalog.Catalog) []scoredModel {
465		var knownModels map[string]string
466		if cat != nil {
467			knownModels = cat.AllConcreteModels(modelcatalog.SurfaceAgentOpenAI)
468		}
469	
470		// Score: 3=catalog, 2=pattern(unused here), 1=uncategorized.
471		scored := make([]scoredModel, 0, len(ids))
472		for pos, id := range ids {
473			sm := scoredModel{ID: id, RankPosition: pos}
474			if ref, ok := knownModels[id]; ok {
475				sm.CatalogRef = ref
476			}
477			scored = append(scored, sm)
478		}
479		return scored
480	}
