501	// catalogCostAndPerf extracts CostInfo and PerfSignal for a model from the catalog.
502	func catalogCostAndPerf(cat *modelcatalog.Catalog, modelID string) (CostInfo, PerfSignal) {
503		entry, ok := cat.LookupModel(modelID)
504		if ok {
505			return CostInfo{
506					InputPerMTok:  catalogEntryInputCost(entry),
507					OutputPerMTok: catalogEntryOutputCost(entry),
508				}, PerfSignal{
509					SpeedTokensPerSec: entry.SpeedTokensPerSec,
510					SWEBenchVerified:  entry.SWEBenchVerified,
511				}
