  3	// route_status.go implements `fiz route-status --overrides`
  4	// (ADR-006 §5). The base `route-status` command lives in routing_smart.go
  5	// and dispatches into this file when --overrides is set.
  6	//
  7	// This is the operator-facing surface that prints override_class_breakdown
  8	// over a recent time window so operators can diagnose where auto-routing
  9	// is mis-deciding. Per ADR-006 §Migration, this is an operator-driven
 10	// feedback loop; automatic learning from this signal is a future ADR.
 11	
 12	import (
 13		"context"
 14		"encoding/json"
 15		"fmt"
 16		"io"
 17		"os"
 18		"sort"
 19		"text/tabwriter"
 20		"time"
 21	
 22		rootfizeau "github.com/DocumentDrivenDX/fizeau"
 23		agentConfig "github.com/DocumentDrivenDX/fizeau/internal/config"
 24	)
 25	
 26	const defaultRouteStatusOverridesWindow = 7 * 24 * time.Hour
 27	
 28	// routeStatusOverridesOutput is the stable JSON envelope emitted by
 29	// `route-status --overrides --json`. The shape is snapshot-tested in
 30	// TestRouteStatusOverridesJSONStable; new fields must be added at the end
 31	// or behind a new flag.
 32	type routeStatusOverridesOutput struct {
 33		Since                    string                           `json:"since"`
 34		WindowStart              time.Time                        `json:"window_start"`
 35		WindowEnd                time.Time                        `json:"window_end"`
 36		AxisFilter               string                           `json:"axis_filter,omitempty"`
 37		AutoAcceptanceRate       float64                          `json:"auto_acceptance_rate"`
 38		OverrideDisagreementRate float64                          `json:"override_disagreement_rate"`
 39		TotalRequests            int                              `json:"total_requests"`
 40		TotalOverrides           int                              `json:"total_overrides"`
 41		OverrideClassBreakdown   []rootfizeau.OverrideClassBucket `json:"override_class_breakdown"`
 42	}
 43	
 44	// cmdRouteStatusOverrides implements the --overrides mode. It is wired in
 45	// from cmdRouteStatus (routing_smart.go); kept here to keep the operator
 46	// surface self-contained.
 47	func cmdRouteStatusOverrides(workDir, since, axis string, jsonOut bool) int {
 48		return runRouteStatusOverrides(workDir, since, axis, jsonOut, os.Stdout, os.Stderr, time.Now().UTC())
 49	}
 50	
 51	func runRouteStatusOverrides(workDir, since, axis string, jsonOut bool, stdout, stderr io.Writer, now time.Time) int {
 52		if err := validateRouteStatusOverridesAxis(axis); err != nil {
 53			fmt.Fprintf(stderr, "error: %s\n", err)
 54			return 2
 55		}
 56	
 57		dur, err := parseRouteStatusOverridesSince(since)
 58		if err != nil {
 59			fmt.Fprintf(stderr, "error: %s\n", err)
 60			return 2
 61		}
 62		start := now.Add(-dur)
 63		end := now
 64	
 65		cfg, err := agentConfig.Load(workDir)
 66		if err != nil {
 67			fmt.Fprintf(stderr, "error: %s\n", err)
 68			return 1
 69		}
 70		svc, err := rootfizeau.New(rootfizeau.ServiceOptions{
 71			ServiceConfig: agentConfig.NewServiceConfig(cfg, workDir),
 72			SessionLogDir: sessionLogDir(workDir, cfg),
 73		})
 74		if err != nil {
 75			fmt.Fprintf(stderr, "error: %s\n", err)
 76			return 1
 77		}
 78	
 79		report, err := svc.UsageReport(context.Background(), rootfizeau.UsageReportOptions{
 80			Since: formatUsageWindowSince(start, end),
 81			Now:   now,
 82		})
 83		if err != nil {
 84			fmt.Fprintf(stderr, "error: %s\n", err)
 85			return 1
 86		}
 87	
 88		metrics := report.RoutingQuality
 89		filtered := filterOverrideBreakdownByAxis(metrics.OverrideClassBreakdown, axis)
 90	
 91		out := routeStatusOverridesOutput{
 92			Since:                    since,
 93			WindowStart:              start,
 94			WindowEnd:                end,
 95			AxisFilter:               axis,
 96			AutoAcceptanceRate:       metrics.AutoAcceptanceRate,
 97			OverrideDisagreementRate: metrics.OverrideDisagreementRate,
 98			TotalRequests:            metrics.TotalRequests,
 99			TotalOverrides:           metrics.TotalOverrides,
100			OverrideClassBreakdown:   filtered,
101		}
102		if out.OverrideClassBreakdown == nil {
103			out.OverrideClassBreakdown = []rootfizeau.OverrideClassBucket{}
104		}
105	
106		if jsonOut {
107			writeRouteStatusOverridesJSON(stdout, out)
108			return 0
109		}
110		writeRouteStatusOverridesText(stdout, out)
111		return 0
112	}
113	
114	// parseRouteStatusOverridesSince parses --since as a Go duration. Empty
115	// means the default 7d window.
116	func parseRouteStatusOverridesSince(spec string) (time.Duration, error) {
117		if spec == "" {
118			return defaultRouteStatusOverridesWindow, nil
119		}
120		d, err := time.ParseDuration(spec)
121		if err != nil {
122			return 0, fmt.Errorf("--since: %w", err)
123		}
124		if d <= 0 {
125			return 0, fmt.Errorf("--since: must be positive, got %s", spec)
126		}
127		return d, nil
128	}
129	
130	// validateRouteStatusOverridesAxis rejects unknown axis values. Empty is
131	// allowed (no filter).
132	func validateRouteStatusOverridesAxis(axis string) error {
133		switch axis {
134		case "", "harness", "provider", "model":
135			return nil
136		default:
137			return fmt.Errorf("--axis: must be one of harness|provider|model, got %q", axis)
138		}
139	}
140	
141	// filterOverrideBreakdownByAxis returns rows where Axis == axis. Empty axis
142	// returns the input unchanged. Rows are returned in the same deterministic
143	// order produced by the aggregator.
144	func filterOverrideBreakdownByAxis(rows []rootfizeau.OverrideClassBucket, axis string) []rootfizeau.OverrideClassBucket {
145		if axis == "" {
146			return rows
147		}
148		out := make([]rootfizeau.OverrideClassBucket, 0, len(rows))
149		for _, r := range rows {
150			if r.Axis == axis {
151				out = append(out, r)
152			}
153		}
154		return out
155	}
156	
157	// sortOverrideBreakdownForDisplay returns a copy sorted by Count desc, then
158	// success rate desc, then deterministic key. The default JSON ordering is
159	// preserved by the aggregator; this is the table-render ordering.
160	func sortOverrideBreakdownForDisplay(rows []rootfizeau.OverrideClassBucket) []rootfizeau.OverrideClassBucket {
161		out := make([]rootfizeau.OverrideClassBucket, len(rows))
162		copy(out, rows)
163		sort.SliceStable(out, func(i, j int) bool {
164			if out[i].Count != out[j].Count {
165				return out[i].Count > out[j].Count
166			}
167			li := bucketSuccessRate(out[i])
168			lj := bucketSuccessRate(out[j])
169			if li != lj {
170				return li > lj
171			}
172			if out[i].PromptFeatureBucket != out[j].PromptFeatureBucket {
173				return out[i].PromptFeatureBucket < out[j].PromptFeatureBucket
174			}
175			if out[i].Axis != out[j].Axis {
176				return out[i].Axis < out[j].Axis
177			}
178			return !out[i].Match && out[j].Match
179		})
180		return out
181	}
182	
183	func bucketSuccessRate(b rootfizeau.OverrideClassBucket) float64 {
184		total := b.SuccessOutcomes + b.StalledOutcomes + b.FailedOutcomes + b.CancelledOutcomes + b.UnknownOutcomes
185		if total == 0 {
186			return 0
187		}
188		return float64(b.SuccessOutcomes) / float64(total)
189	}
190	
191	func writeRouteStatusOverridesJSON(w io.Writer, out routeStatusOverridesOutput) {
192		enc := json.NewEncoder(w)
193		enc.SetIndent("", "  ")
194		_ = enc.Encode(out)
195	}
196	
197	func writeRouteStatusOverridesText(w io.Writer, out routeStatusOverridesOutput) {
198		fmt.Fprintf(w, "Window: %s .. %s (%s)\n",
199			out.WindowStart.Format(time.RFC3339),
200			out.WindowEnd.Format(time.RFC3339),
201			windowDurationLabel(out.Since))
202		if out.AxisFilter != "" {
203			fmt.Fprintf(w, "Axis filter: %s\n", out.AxisFilter)
204		}
205		fmt.Fprintf(w, "Auto-acceptance rate: %.3f (%d / %d)\n",
206			out.AutoAcceptanceRate,
207			out.TotalRequests-out.TotalOverrides,
208			out.TotalRequests)
209		fmt.Fprintf(w, "Override disagreement rate: %.3f (%d overrides)\n",
210			out.OverrideDisagreementRate,
211			out.TotalOverrides)
212	
213		if len(out.OverrideClassBreakdown) == 0 {
214			fmt.Fprintln(w)
215			fmt.Fprintln(w, "No override events recorded in this window.")
216			return
217		}
218	
219		fmt.Fprintln(w)
220		tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
221		fmt.Fprintln(tw, "PROMPT_FEATURES\tAXIS\tMATCH\tCOUNT\tSUCCESS%\tSUCCESS\tSTALLED\tFAILED\tCANCELLED\tUNKNOWN")
222		for _, b := range sortOverrideBreakdownForDisplay(out.OverrideClassBreakdown) {
223			successPct := bucketSuccessRate(b) * 100
224			fmt.Fprintf(tw, "%s\t%s\t%t\t%d\t%.1f%%\t%d\t%d\t%d\t%d\t%d\n",
225				b.PromptFeatureBucket, b.Axis, b.Match, b.Count, successPct,
226				b.SuccessOutcomes, b.StalledOutcomes, b.FailedOutcomes,
227				b.CancelledOutcomes, b.UnknownOutcomes)
228		}
229		_ = tw.Flush()
230	}
231	
232	func windowDurationLabel(since string) string {
233		if since == "" {
234			return "default 7d"
235		}
236		return since
237	}
238	
239	// formatUsageWindowSince builds the date-range form
240	// "RFC3339..RFC3339" that internal/session.ParseUsageWindow accepts. We
241	// route through it (rather than a duration form) because the public
242	// UsageReport API only takes a string.
243	func formatUsageWindowSince(start, end time.Time) string {
244		return start.UTC().Format(time.RFC3339) + ".." + end.UTC().Format(time.RFC3339)
245	}

