184	func (s *service) routeUtilizationEvidence(provider, serverInstance, endpoint, model string) RouteUtilizationState {
185		if s == nil || s.routeUtilization == nil {
186			return RouteUtilizationState{}
187		}
188		keyProvider := strings.TrimSpace(provider)
189		keyServerInstance := strings.TrimSpace(serverInstance)
190		keyEndpoint := strings.TrimSpace(endpoint)
191		if base, ep, ok := splitEndpointProviderRef(keyProvider); ok {
192			keyProvider = base
193			if keyEndpoint == "" {
194				keyEndpoint = ep
195			}
196		}
197		if keyServerInstance == "" {
198			keyServerInstance = keyEndpoint
199		}
200		sample, ok := s.routeUtilization.Sample(keyProvider, keyServerInstance, model)
201		if !ok && keyEndpoint != "" && keyEndpoint != keyServerInstance {
202			sample, ok = s.routeUtilization.Sample(keyProvider, keyEndpoint, model)
203		}
204		if !ok {
205			return RouteUtilizationState{}
206		}
207		return routeUtilizationStateFromSample(sample)
