210	func routeUtilizationStateFromSample(sample utilization.EndpointUtilization) RouteUtilizationState {
211		out := RouteUtilizationState{
212			Source:     string(sample.Source),
213			Freshness:  string(sample.Freshness),
214			ObservedAt: sample.ObservedAt,
215		}
216		if sample.ActiveRequests != nil {
217			out.ActiveRequests = utilization.Int(*sample.ActiveRequests)
218		}
219		if sample.QueuedRequests != nil {
220			out.QueuedRequests = utilization.Int(*sample.QueuedRequests)
221		}
222		if sample.MaxConcurrency != nil {
223			out.MaxConcurrency = utilization.Int(*sample.MaxConcurrency)
224		}
225		if sample.CacheUsage != nil {
226			v := *sample.CacheUsage
227			out.CachePressure = &v
228		}
229		if out.CachePressure == nil && sample.MaxConcurrency != nil && *sample.MaxConcurrency > 0 {
230			total := 0
231			if sample.ActiveRequests != nil {
232				total += *sample.ActiveRequests
233			}
234			if sample.QueuedRequests != nil {
235				total += *sample.QueuedRequests
236			}
237			pressure := float64(total) / float64(*sample.MaxConcurrency)
238			out.CachePressure = &pressure
239		}
240		return out
241	}
