274	// escalateProfileLadder walks routing.ProfileEscalationLadder when Resolve
275	// returns a "no eligible candidate" error and the request's profile is in
276	// the ladder. Returns (true, decision, nil) when a higher tier resolves to
277	// an eligible candidate, or (true, nil, *routing.ErrNoLiveProvider) when
278	// the entire remaining ladder is also empty. Returns (false, _, _) when
279	// escalation does not apply (hard pin error, profile not in ladder, etc.).
280	func escalateProfileLadder(req routing.Request, in routing.Inputs, origErr error) (bool, *routing.Decision, error) {
281		if origErr == nil || req.Profile == "" {
282			return false, nil, nil
283		}
284		if !shouldEscalateOnError(origErr) {
285			return false, nil, nil
286		}
287		startIdx := -1
288		for i, p := range routing.ProfileEscalationLadder {
289			if p == req.Profile {
290				startIdx = i
291				break
292			}
293		}
294		if startIdx < 0 {
295			return false, nil, nil
296		}
297		for i := startIdx + 1; i < len(routing.ProfileEscalationLadder); i++ {
298			probe := req
299			probe.Profile = routing.ProfileEscalationLadder[i]
300			dec, err := routing.Resolve(probe, in)
301			if err == nil && dec != nil && dec.Harness != "" {
302				return true, dec, nil
303			}
304		}
305		return true, nil, &routing.ErrNoLiveProvider{
306			PromptTokens:  req.EstimatedPromptTokens,
307			RequiresTools: req.RequiresTools,
308			StartingTier:  req.Profile,
309		}
310	}
311	
312	// shouldEscalateOnError gates ladder escalation to "no eligible candidate"
313	// errors. Hard caller-pin conflicts (ErrHarnessModelIncompatible,
314	// ErrProfilePinConflict) are surfaced as-is — escalating past an explicit
315	// pin would silently change the caller's intent.
316	func shouldEscalateOnError(err error) bool {
317		var modelConstraintAmbiguous *ErrModelConstraintAmbiguous
318		if errors.As(err, &modelConstraintAmbiguous) {
319			return false
320		}
321		var modelConstraintNoMatch *ErrModelConstraintNoMatch
322		if errors.As(err, &modelConstraintNoMatch) {
323			return false
324		}
325		var modelErr *routing.ErrHarnessModelIncompatible
326		if errors.As(err, &modelErr) {
327			return false
328		}
329		var pinErr *routing.ErrProfilePinConflict
330		if errors.As(err, &pinErr) {
331			return false
332		}
333		return true
334	}
335	
336	func publicRoutingError(err error, candidates []RouteCandidate) error {
337		var modelErr *routing.ErrHarnessModelIncompatible
338		if errors.As(err, &modelErr) {
339			return withRouteCandidates(&ErrHarnessModelIncompatible{
340				Harness:         modelErr.Harness,
341				Model:           modelErr.Model,
342				SupportedModels: append([]string(nil), modelErr.SupportedModels...),
343			}, candidates)
344		}
345		var profileErr *routing.ErrProfilePinConflict
346		if errors.As(err, &profileErr) {
347			return withRouteCandidates(&ErrProfilePinConflict{
348				Profile:           profileErr.Profile,
349				ConflictingPin:    profileErr.ConflictingPin,
350				ProfileConstraint: profileErr.ProfileConstraint,
351			}, candidates)
352		}
353		var noProfileErr *routing.ErrNoProfileCandidate
354		if errors.As(err, &noProfileErr) {
355			return withRouteCandidates(&ErrNoProfileCandidate{
356				Profile:           noProfileErr.Profile,
357				MissingCapability: noProfileErr.MissingCapability,
358				Rejected:          noProfileErr.Rejected,
359			}, candidates)
360		}

360		}
361		var noLiveErr *routing.ErrNoLiveProvider
362		if errors.As(err, &noLiveErr) {
363			return withRouteCandidates(&ErrNoLiveProvider{
364				PromptTokens:  noLiveErr.PromptTokens,
365				RequiresTools: noLiveErr.RequiresTools,
366				StartingTier:  noLiveErr.StartingTier,
367			}, candidates)
368		}
369		var quotaErr *routing.ErrAllProvidersQuotaExhausted
370		if errors.As(err, &quotaErr) {
371			return withRouteCandidates(&NoViableProviderForNow{
372				RetryAfter:         quotaErr.RetryAfter,
373				ExhaustedProviders: append([]string(nil), quotaErr.ExhaustedProviders...),
374			}, candidates)
375		}
376		return withRouteCandidates(err, candidates)
377	}
