389	func (s *service) applyRouteAttemptCooldowns(in *routing.Inputs) {
390		if in == nil {
391			return
392		}
393		ttl := s.routeAttemptTTL()
394		records := s.activeRouteAttempts(time.Now(), ttl)
395		if len(records) == 0 {
396			return
397		}
398		if in.ProviderCooldowns == nil {
399			in.ProviderCooldowns = make(map[string]time.Time)
400		}
401		if in.CooldownDuration <= 0 {
402			in.CooldownDuration = ttl
403		}
404		for _, record := range records {
405			if record.Key.Provider != "" {
406				existing, ok := in.ProviderCooldowns[record.Key.Provider]
407				if !ok || record.RecordedAt.After(existing) {
408					in.ProviderCooldowns[record.Key.Provider] = record.RecordedAt
409				}
410			}
411			if record.Key.Provider == "" && record.Key.Harness != "" {
412				for i := range in.Harnesses {
413					if in.Harnesses[i].Name == record.Key.Harness {
414						in.Harnesses[i].InCooldown = true
415					}
416				}
417			}
418		}
419	}
