421	func (s *service) routeAttemptTTL() time.Duration {
422		if s.opts.ServiceConfig == nil {
423			return defaultRouteAttemptCooldown
424		}
425		ttl := s.opts.ServiceConfig.HealthCooldown()
426		if ttl <= 0 {
427			return defaultRouteAttemptCooldown
428		}
429		return ttl
430	}
