432	// buildRoutingInputs assembles routing.Inputs from the service's registry
433	// and ServiceConfig. When the service has a catalog cache attached (v0.9.2+),
434	// each configured provider's ProviderEntry is populated with DiscoveredIDs
435	// from the cache's live /v1/models probe, so routing.FuzzyMatch matches the
436	// request against IDs the server actually serves rather than the configured
437	// default-model string.
438	//
439	// ctx is used for cache probes with a short deadline; the cache's
440	// stale-while-revalidate flow makes most calls non-blocking.
441	func (s *service) buildRoutingInputs(ctx context.Context) routing.Inputs {
442		return s.buildRoutingInputsWithCatalog(ctx, serviceRoutingCatalog())
443	}
