445	func (s *service) buildRoutingInputsWithCatalog(ctx context.Context, cat *modelcatalog.Catalog) routing.Inputs {
446		statuses := s.registry.Discover()
447		statusByName := make(map[string]harnesses.HarnessStatus, len(statuses))
448		for _, st := range statuses {
449			statusByName[st.Name] = st
450		}
451		now := time.Now().UTC()
452	
453		var entries []routing.HarnessEntry
454		for _, name := range s.registry.Names() {
455			cfg, ok := s.registry.Get(name)
456			if !ok {
457				continue
458			}
459			st := statusByName[name]
460			entry := routing.HarnessEntry{
461				Name:                name,
462				Surface:             cfg.Surface,
463				CostClass:           cfg.CostClass,
464				IsLocal:             cfg.IsLocal,
465				IsSubscription:      cfg.IsSubscription,
466				IsHTTPProvider:      cfg.IsHTTPProvider,
467				AutoRoutingEligible: cfg.AutoRoutingEligible,
468				TestOnly:            cfg.TestOnly,
469				ExactPinSupport:     cfg.ExactPinSupport,
470				DefaultModel:        cfg.DefaultModel,
471				SupportedModels:     subprocessHarnessModelIDs(name, cfg),
472				SupportedReasoning:  supportedReasoning(cfg),
473				MaxReasoningTokens:  cfg.MaxReasoningTokens,
474				SupportedPerms:      supportedPermissions(cfg),
475				SupportsTools:       true, // all builtin harnesses support tools today
476				Available:           st.Available,
477				QuotaOK:             true,
478				QuotaTrend:          routing.QuotaTrendUnknown,
479				// SubscriptionOK defaults to true and is refined by subscription
480				// harness quota caches below.
481				SubscriptionOK: true,
482			}
483			if name == "fiz" && s.opts.ServiceConfig == nil {
484				entry.AutoRoutingEligible = false
485			}
486	
487			if qs, ok := subscriptionQuotaForHarness(name, time.Now()); ok {
488				entry.QuotaOK = qs.OK
489				entry.QuotaStale = qs.Present && !qs.Fresh
490				entry.SubscriptionOK = qs.OK
491				entry.QuotaPercentUsed = qs.PercentUsed
492				entry.QuotaTrend = qs.Trend
493				entry.QuotaReason = qs.Reason
494			}
495	
496			// Native "fiz" harness: enumerate live configured provider endpoints.
497			if name == "fiz" && s.opts.ServiceConfig != nil {
498				for _, pname := range s.opts.ServiceConfig.ProviderNames() {
499					pcfg, ok := s.opts.ServiceConfig.Provider(pname)
500					if !ok {
501						continue
502					}
503					entry.Providers = append(entry.Providers, s.liveProviderEntries(ctx, pname, pcfg, cat)...)
504				}
505				// Tool support for the agent harness is per-(provider, model);
506				// the harness-level baseline is whether ANY provider supports
507				// tools. Engine OR-combines harness and provider SupportsTools
508				// so this lets a per-model no_tools catalog flag actually fire
509				// the RequiresTools gate when every provider's resolved model
510				// is no-tools.
511				if len(entry.Providers) > 0 {
512					entry.SupportsTools = anyProviderSupportsTools(entry.Providers)
513				} else {
514					entry.Available = false
515				}
516			}
517			s.applySubscriptionRoutingCost(&entry, cat)
518			entries = append(entries, entry)
519		}
520		successRate, latencyMS := s.routeMetricSignals(now, s.routeAttemptTTL())
521		return routing.Inputs{
522			Harnesses:                   entries,
523			ProviderSuccessRate:         successRate,
524			ObservedLatencyMS:           latencyMS,
525			ProviderQuotaExhaustedUntil: s.providerQuotaExhaustedUntil(now),
526			CatalogResolver:             serviceRoutingCatalogResolver(cat),
527			CatalogCandidatesResolver:   serviceRoutingCatalogCandidatesResolver(cat),
528			ModelEligibility:            serviceRoutingModelEligibility(cat),
529			ReasoningResolver:           serviceRoutingReasoningResolver(cat),
530			EndpointLoadResolver:        s.routeEndpointLoadsResolver(now),
531		}
532	}
