534	// providerQuotaExhaustedUntil snapshots the per-provider quota state machine
535	// at the given instant for the routing engine. Returns nil when no provider
536	// is currently in quota_exhausted state, which keeps the routing path
537	// allocation-free in the common case.
538	func (s *service) providerQuotaExhaustedUntil(now time.Time) map[string]time.Time {
539		if s == nil || s.providerQuota == nil {
540			return nil
541		}
542		return s.providerQuota.ExhaustedAt(now)
543	}
