545	// startQuotaRecoveryProbeLoop spawns the goroutine that periodically probes
546	// quota_exhausted providers and either restores them to available or extends
547	// their retry_after with bounded backoff. The goroutine is tied to
548	// QuotaRefreshContext (or context.Background()) so server callers can cancel
549	// it on shutdown.
550	func (s *service) startQuotaRecoveryProbeLoop() {
551		if s == nil || s.providerQuota == nil {
552			return
553		}
554		ctx := s.opts.QuotaRefreshContext
555		if ctx == nil {
556			ctx = context.Background()
557		}
558		probe := s.quotaRecoveryProber()
559		if probe == nil {
560			return
561		}
562		go runQuotaRecoveryProbeLoop(ctx, s.providerQuota, probe, defaultQuotaRecoveryFallbackInterval, nil, nil)
563	}
564	
565	// quotaRecoveryProber returns the QuotaRecoveryProber used by the recovery
566	// loop. It looks up the provider entry in ServiceConfig and reuses the same
567	// probeProviderStatus the HealthCheck endpoint uses; a "connected" status
568	// counts as recovery, anything else is reported as a probe failure so the
569	// retry_after gets extended with backoff.
570	func (s *service) quotaRecoveryProber() QuotaRecoveryProber {
571		sc := s.opts.ServiceConfig
572		if sc == nil {
573			return nil
574		}
575		return func(ctx context.Context, name string) error {
576			entry, ok := sc.Provider(name)
577			if !ok {
578				return fmt.Errorf("provider %q not found", name)
579			}
580			probeCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
581			defer cancel()
582			probe := probeProviderStatus(probeCtx, entry, time.Now().UTC())
583			if probe.status == "connected" {
584				return nil
585			}
586			if probe.detail != "" {
587				return fmt.Errorf("%s", probe.detail)
588			}
589			return fmt.Errorf("%s", probe.status)
590		}
591	}
